UPDATE tasks SET status = #{task.status}, current_stage = #{task.currentStage}, started_at = #{task.startedAt},
  finished_at = #{task.finishedAt}, result_path = #{task.resultPath}, error_code = #{task.errorCode}, error_message = #{task.errorMessage}
WHERE id = #{task.id} AND status IN ('QUEUED', 'RUNNING')
  AND status = #{expectedStatus} AND current_stage <=> #{expectedStage,jdbcType=VARCHAR}
